using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using IdleRestaurant;
public static class PeopleAssetAudit053{public static object Main(){var c=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>().catalog;var errors=new List<string>();var prefabs=c.guestVariants.Concat(c.chefVariants).Concat(c.hostVariants).Concat(c.janitorVariants).ToArray();foreach(var p in prefabs){if(!p){errors.Add("Missing prefab");continue;}var rig=p.GetComponent<RestaurantActorRig>();if(!rig||!rig.Valid||!rig.leftKnee||!rig.rightKnee)errors.Add(p.name+" rig");foreach(var t in p.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)errors.Add(p.name+" missing script "+t.name);foreach(var f in p.GetComponentsInChildren<MeshFilter>(true))if(!f.sharedMesh)errors.Add(p.name+" missing mesh "+f.name);foreach(var ren in p.GetComponentsInChildren<Renderer>(true))if(ren.sharedMaterials.Any(m=>!m||!m.shader))errors.Add(p.name+" missing material "+ren.name);}
var result=new{status=errors.Count==0?"PASS":"FAIL",prefabs=prefabs.Length,guestVariants=c.guestVariants.Length,chefVariants=c.chefVariants.Length,hostVariants=c.hostVariants.Length,janitorVariants=c.janitorVariants.Length,errors,scope="All authored people prefab rig, mesh, material and missing-script references"};File.WriteAllText("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/PeopleAssetAudit.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
